<script setup>
import {ref,computed} from 'vue';import {useRouter} from 'vue-router';import {useCart} from '../composables/cart';import {money} from '../data/catalog';const {groups,modes,count,subtotal,delivery,total,result,clear}=useCart();const router=useRouter();const form=ref({name:'',email:'',phone:'',address:'',city:'',state:'Lagos',note:''}),provider=ref('Paystack'),error=ref(''),busy=ref(false);const needsAddress=computed(()=>groups.value.some(g=>modes.value[g.seller.id]!=='pickup'));function submit(){if(busy.value||!count.value)return;const f=form.value;if(!f.name.trim()||!/^\S+@\S+\.\S+$/.test(f.email)||f.phone.replace(/\D/g,'').length<10||(needsAddress.value&&(!f.address.trim()||!f.city.trim()||!f.state.trim()))){error.value='Please complete the required contact and delivery details.';return}busy.value=true;result.value={reference:'DEMO-'+crypto.randomUUID().slice(0,8).toUpperCase(),total:total.value,provider:provider.value,groups:groups.value.map(g=>({name:g.seller.name,mode:modes.value[g.seller.id]||'delivery'}))};clear();router.push('/result')}
</script>
<template><div class="shell py-9"><h1 class="text-4xl font-black">Checkout</h1><p class="mt-2 text-gray-500">Basket → Information & fulfilment → Demo payment</p><div v-if="!count" class="panel mt-6">Your basket is empty. <router-link to="/">Continue shopping</router-link></div><form v-else class="mt-7 grid items-start gap-6 lg:grid-cols-[1fr_380px]" @submit.prevent="submit"><div class="space-y-5"><section class="panel" data-aos="fade-up"><h2 class="mb-4 text-xl font-bold">01 · Contact details</h2><div class="grid gap-4 sm:grid-cols-2"><v-text-field v-model="form.name" label="Full name" variant="outlined" required/><v-text-field v-model="form.email" label="Email" type="email" variant="outlined" required/><v-text-field v-model="form.phone" label="Phone number" type="tel" variant="outlined" required/></div></section><section class="panel"><h2 class="mb-4 text-xl font-bold">02 · Delivery or pickup</h2><div v-for="g in groups" :key="g.seller.id" class="mb-5 rounded-xl border border-green-100 p-4"><h3 class="font-bold">{{g.seller.name}}</h3><p class="mb-3 text-sm text-gray-500">{{g.seller.location}}</p><div class="flex flex-wrap gap-2"><button type="button" :class="modes[g.seller.id]!=='pickup'?'primary':'secondary'" @click="modes[g.seller.id]='delivery'"><i class="fa-solid fa-truck"></i> Delivery {{money(g.seller.fee)}}</button><button type="button" :class="modes[g.seller.id]==='pickup'?'primary':'secondary'" @click="modes[g.seller.id]='pickup'"><i class="fa-solid fa-store"></i> Free pickup</button></div></div><div v-if="needsAddress"><v-text-field v-model="form.address" label="Street address" variant="outlined" required/><div class="grid gap-3 sm:grid-cols-2"><v-text-field v-model="form.city" label="City" variant="outlined" required/><v-text-field v-model="form.state" label="State" variant="outlined" required/></div></div><v-textarea v-model="form.note" label="Order notes (optional)" variant="outlined" rows="2"/></section><section class="panel"><h2 class="mb-4 text-xl font-bold">03 · Payment method</h2><v-radio-group v-model="provider" hide-details><v-radio label="Paystack (demo)" value="Paystack"/><v-radio label="Flutterwave (demo)" value="Flutterwave"/></v-radio-group><p class="mt-3 text-sm text-gray-500">No real payment or notification will be sent.</p></section></div><aside class="panel lg:sticky lg:top-28"><h2 class="mb-4 text-xl font-black">Order summary</h2><div v-for="g in groups" :key="g.seller.id" class="mb-4 border-b border-green-100 pb-3"><h3 class="font-bold text-green-800">{{g.seller.name}}</h3><p v-for="l in g.items" :key="l.key" class="my-2 flex justify-between gap-2 text-sm"><span>{{l.qty}} × {{l.name}} {{l.option}}</span><b>{{money(l.price*l.qty)}}</b></p><p class="flex justify-between text-sm">Fulfilment <span>{{money(g.fee)}}</span></p></div><p class="flex justify-between">Subtotal <b>{{money(subtotal)}}</b></p><p class="my-2 flex justify-between">Delivery <b>{{money(delivery)}}</b></p><p class="my-4 flex justify-between text-xl font-black">Total <span>{{money(total)}}</span></p><p v-if="error" role="alert" class="mb-3 text-red-700">{{error}}</p><button type="submit" class="primary w-full" :disabled="busy"><i class="fa-solid fa-lock"></i> Simulate payment</button></aside></form></div></template>
